/**
 * Mock package whose type names coincide with built-in DOM and ES types
 * but describe unrelated things.
 */

/**
 * A numeric range, unrelated to the DOM `Range`.
 */
export interface Range {
	start: number;
	end: number;
}

/**
 * A namespace unrelated to the built-in `Intl`.
 */
export declare namespace Intl {
	interface NumberFormat {
		pattern: string;
	}
}

/**
 * A package alias of a built-in type.
 */
export type Locale = globalThis.Intl.LocalesArgument;

/**
 * A package alias of a built-in interface.
 */
export type PackageRange = globalThis.Range;
